import{_ as r,a0 as o,w as m,s as l,ao as p,I as n,a1 as i,A as a,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"在 Linux 下使用 RAID（一）：使用 mdadm 工具創建軟件 RAID 0 （條帶化） | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 下使用 RAID（一）：使用 mdadm 工具創建軟件 RAID 0 （條帶化） | LCTT (RAID) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 下使用 RAID（一）：使用 mdadm 工具創建軟件 RAID 0 （條帶化） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 下使用 RAID（一）：使用 mdadm 工具創建軟件 RAID 0 （條帶化） | LCTT (RAID) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RAID/Part 2 - Creating Software RAID0 (Stripe) on ‘Two Devices’ Using ‘mdadm’ Tool in Linux","title":"在 Linux 下使用 RAID（一）：使用 mdadm 工具創建軟件 RAID 0 （條帶化）","tag":"RAID","desc":""},"relativePath":"RAID/Part 2 - Creating Software RAID0 (Stripe) on ‘Two Devices’ Using ‘mdadm’ Tool in Linux.md","filePath":"[post].md"}'),c={name:"RAID/Part 2 - Creating Software RAID0 (Stripe) on ‘Two Devices’ Using ‘mdadm’ Tool in Linux.md"};function s(D,e,A,I,R,u){const d=o("Link");return m(),l("div",null,[e[14]||(e[14]=p('<h1 id="在-linux-下使用-raid-一-使用-mdadm-工具創建軟件-raid-0-條帶化" tabindex="-1">在 Linux 下使用 RAID（一）：使用 mdadm 工具創建軟件 RAID 0 （條帶化） <a class="header-anchor" href="#在-linux-下使用-raid-一-使用-mdadm-工具創建軟件-raid-0-條帶化" aria-label="Permalink to “在 Linux 下使用 RAID（一）：使用 mdadm 工具創建軟件 RAID 0 （條帶化）”">​</a></h1><p>RAID 即廉價磁盤冗餘陣列，其高可用性和可靠性適用於大規模環境中，相比正常使用，數據更需要被保護。RAID 是一些磁盤的集合，是包含一個陣列的邏輯卷。驅動器可以組合起來成為一個陣列或稱為（組的）集合。</p><p>創建 RAID 最少應使用2個連接到 RAID 控制器的磁盤組成，來構成邏輯卷，可以根據定義的 RAID 級別將更多的驅動器添加到一個陣列中。不使用物理硬件創建的 RAID 被稱為軟件 RAID。軟件 RAID 也叫做窮人 RAID。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Raid0-in-Linux.jpg" alt="Setup RAID0 in Linux"></p><p><em>在 Linux 中創建 RAID0</em></p><p>使用 RAID 的主要目的是為了在發生單點故障時保存數據，如果我們使用單個磁盤來存儲數據，如果它損壞了，那麼就沒有機會取回我們的數據了，為了防止數據丟失我們需要一個容錯的方法。所以，我們可以使用多個磁盤組成 RAID 陣列。</p><h4 id="在-raid-0-中條帶是什麼" tabindex="-1">在 RAID 0 中條帶是什麼 <a class="header-anchor" href="#在-raid-0-中條帶是什麼" aria-label="Permalink to “在 RAID 0 中條帶是什麼”">​</a></h4><p>條帶是通過將數據在同時分割到多個磁盤上。假設我們有兩個磁盤，如果我們將數據保存到該邏輯捲上，它會將數據保存在兩個磁盤上。使用 RAID 0 是為了獲得更好的性能，但是如果驅動器中一個出現故障，我們將不能得到完整的數據。因此，使用 RAID 0 不是一種好的做法。唯一的解決辦法就是安裝有 RAID 0 邏輯卷的操作系統來提高重要文件的安全性。</p><ul><li>RAID 0 性能較高。</li><li>在 RAID 0 上，空間零浪費。</li><li>零容錯（如果硬盤中的任何一個發生故障，無法取回數據）。</li><li>寫和讀性能都很好。</li></ul><h4 id="要求" tabindex="-1">要求 <a class="header-anchor" href="#要求" aria-label="Permalink to “要求”">​</a></h4><p>創建 RAID 0 允許的最小磁盤數目是2個，但你可以添加更多的磁盤，不過數目應該是2，4，6，8等的偶數。如果你有一個物理 RAID 卡並且有足夠的端口，你可以添加更多磁盤。</p><p>在這裏，我們沒有使用硬件 RAID，此設置只需要軟件 RAID。如果我們有一個物理硬件 RAID 卡，我們可以從它的功能界面訪問它。有些主板默認內建 RAID 功能，還可以使用 Ctrl + I 鍵訪問它的界面。</p><p>如果你是剛開始設置 RAID，請閲讀我們前面的文章，我們已經介紹了一些關於 RAID 基本的概念。</p>',13)),n("ul",null,[n("li",null,[i(d,{href:"https://linux.cn/article-6085-1.html"},{default:a(()=>[...e[0]||(e[0]=[t("介紹 RAID 的級別和概念",-1)])]),_:1})])]),e[15]||(e[15]=p(`<p><strong>我的服務器設置</strong></p><pre><code>操作系統 :	CentOS 6.5 Final
IP 地址	 :	192.168.0.225
兩塊盤	 :	20 GB each
</code></pre><p>這是9篇系列教程的第2部分，在這部分，我們將看看如何能夠在 Linux 上創建和使用 RAID 0（條帶化），以名為 sdb 和 sdc 兩個 20GB 的硬盤為例。</p><h3 id="第1步-更新系統和安裝管理-raid-的-mdadm-軟件" tabindex="-1">第1步：更新系統和安裝管理 RAID 的 mdadm 軟件 <a class="header-anchor" href="#第1步-更新系統和安裝管理-raid-的-mdadm-軟件" aria-label="Permalink to “第1步：更新系統和安裝管理 RAID 的 mdadm 軟件”">​</a></h3><p>1、 在 Linux 上設置 RAID 0 前，我們先更新一下系統，然後安裝<code>mdadm</code> 包。mdadm 是一個小程序，這將使我們能夠在Linux下配置和管理 RAID 設備。</p><pre><code># yum clean all &amp;&amp; yum update
# yum install mdadm -y
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/install-mdadm-in-linux.png" alt="install mdadm in linux"></p><p><em>安裝 mdadm 工具</em></p><h3 id="第2步-確認連接了兩個-20gb-的硬盤" tabindex="-1">第2步：確認連接了兩個 20GB 的硬盤 <a class="header-anchor" href="#第2步-確認連接了兩個-20gb-的硬盤" aria-label="Permalink to “第2步：確認連接了兩個 20GB 的硬盤”">​</a></h3><p>2、 在創建 RAID 0 前，請務必確認兩個硬盤能被檢測到，使用下面的命令確認。</p><pre><code># ls -l /dev | grep sd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-Hard-Drives.png" alt="Check Hard Drives in Linux"></p><p><em>檢查硬盤</em></p><p>3、 一旦檢測到新的硬盤驅動器，同時檢查是否連接的驅動器已經被現有的 RAID 使用，使用下面的<code>mdadm</code> 命令來查看。</p><pre><code># mdadm --examine /dev/sd[b-c]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-Drives-using-RAID.png" alt="Check RAID Devices in Linux"></p><p><em>檢查 RAID 設備</em></p><p>從上面的輸出我們可以看到，沒有任何 RAID 使用 sdb 和 sdc 這兩個驅動器。</p><h3 id="第3步-創建-raid-分區" tabindex="-1">第3步：創建 RAID 分區 <a class="header-anchor" href="#第3步-創建-raid-分區" aria-label="Permalink to “第3步：創建 RAID 分區”">​</a></h3><p>4、 現在用 sdb 和 sdc 創建 RAID 的分區，使用 fdisk 命令來創建。在這裏，我將展示如何創建 sdb 驅動器上的分區。</p><pre><code># fdisk /dev/sdb
</code></pre><p>請按照以下説明創建分區。</p><ul><li>按<code>n</code> 創建新的分區。</li><li>然後按<code>P</code> 選擇主分區。</li><li>接下來選擇分區號為1。</li><li>只需按兩次回車鍵選擇默認值即可。</li><li>然後，按<code>P</code> 來顯示創建好的分區。</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Create-Partitions-in-Linux.png" alt="Create Partitions in Linux"></p><p><em>創建分區</em></p><p>請按照以下説明將分區創建為 Linux 的 RAID 類型。</p><ul><li>按<code>L</code>，列出所有可用的類型。</li><li>按<code>t</code> 去修改分區。</li><li>鍵入<code>fd</code> 設置為 Linux 的 RAID 類型，然後按回車確認。</li><li>然後再次使用<code>p</code>查看我們所做的更改。</li><li>使用<code>w</code>保存更改。</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Create-RAID-Partitions.png" alt="Create RAID Partitions"></p><p><em>在 Linux 上創建 RAID 分區</em></p><p><strong>注</strong>: 請使用上述步驟同樣在 sdc 驅動器上創建分區。</p><p>5、 創建分區後，驗證這兩個驅動器是否正確定義 RAID，使用下面的命令。</p><pre><code># mdadm --examine /dev/sd[b-c]
# mdadm --examine /dev/sd[b-c]1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Verify-RAID-Partitions.png" alt="Verify RAID Partitions"></p><p><em>驗證 RAID 分區</em></p><h3 id="第4步-創建-raid-md-設備" tabindex="-1">第4步：創建 RAID md 設備 <a class="header-anchor" href="#第4步-創建-raid-md-設備" aria-label="Permalink to “第4步：創建 RAID md 設備”">​</a></h3><p>6、 現在使用以下命令創建 md 設備（即 /dev/md0），並選擇 RAID 合適的級別。</p><pre><code># mdadm -C /dev/md0 -l raid0 -n 2 /dev/sd[b-c]1
# mdadm --create /dev/md0 --level=stripe --raid-devices=2 /dev/sd[b-c]1
</code></pre><ul><li>-C – 創建</li><li>-l – 級別</li><li>-n – RAID 設備數</li></ul><p>7、 一旦 md 設備已經建立，使用如下命令可以查看 RAID 級別，設備和陣列的使用狀態。</p><pre><code># cat /proc/mdstat
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Verify-RAID-Level.png" alt="Verify RAID Level"></p><p><em>查看 RAID 級別</em></p><pre><code># mdadm -E /dev/sd[b-c]1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Verify-RAID-Device.png" alt="Verify RAID Device"></p><p><em>查看 RAID 設備</em></p><pre><code># mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Verify-RAID-Array.png" alt="Verify RAID Array"></p><p><em>查看 RAID 陣列</em></p><h3 id="第5步-給-raid-設備創建文件系統" tabindex="-1">第5步：給 RAID 設備創建文件系統 <a class="header-anchor" href="#第5步-給-raid-設備創建文件系統" aria-label="Permalink to “第5步：給 RAID 設備創建文件系統”">​</a></h3><p>8、 將 RAID 設備 /dev/md0 創建為 ext4 文件系統，並掛載到 /mnt/raid0 下。</p><pre><code># mkfs.ext4 /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Create-ext4-Filesystem.png" alt="Create ext4 Filesystem in Linux"></p><p><em>創建 ext4 文件系統</em></p><p>9、 在 RAID 設備上創建好 ext4 文件系統後，現在創建一個掛載點（即 /mnt/raid0），並將設備 /dev/md0 掛載在它下。</p><pre><code># mkdir /mnt/raid0
# mount /dev/md0 /mnt/raid0/
</code></pre><p>10、下一步，使用 df 命令驗證設備 /dev/md0 是否被掛載在 /mnt/raid0 下。</p><pre><code># df -h
</code></pre><p>11、 接下來，在掛載點 /mnt/raid0 下創建一個名為<code>tecmint.txt</code> 的文件，為創建的文件添加一些內容，並查看文件和目錄的內容。</p><pre><code># touch /mnt/raid0/tecmint.txt
# echo &quot;Hi everyone how you doing ?&quot; &gt; /mnt/raid0/tecmint.txt
# cat /mnt/raid0/tecmint.txt
# ls -l /mnt/raid0/
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Verify-Mount-Device.png" alt="Verify Mount Device"></p><p><em>驗證掛載的設備</em></p><p>12、 當你驗證掛載點後，就可以將它添加到 /etc/fstab 文件中。</p><pre><code># vim /etc/fstab
</code></pre><p>添加以下條目，根據你的安裝位置和使用文件系統的不同，自行做修改。</p><pre><code>/dev/md0                /mnt/raid0              ext4    deaults         0 0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Add-Device-to-Fstab.png" alt="Add Device to Fstab"></p><p><em>添加設備到 fstab 文件中</em></p><p>13、 使用 mount 命令的 <code>-a</code> 來檢查 fstab 的條目是否有誤。</p><pre><code># mount -av
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-Errors-in-Fstab.png" alt="Check Errors in Fstab"></p><p><em>檢查 fstab 文件是否有誤</em></p><h3 id="第6步-保存-raid-配置" tabindex="-1">第6步：保存 RAID 配置 <a class="header-anchor" href="#第6步-保存-raid-配置" aria-label="Permalink to “第6步：保存 RAID 配置”">​</a></h3><p>14、 最後，保存 RAID 配置到一個文件中，以供將來使用。我們再次使用帶有<code>-s</code> (scan) 和<code>-v</code> (verbose) 選項的 <code>mdadm</code> 命令，如圖所示。</p><pre><code># mdadm -E -s -v &gt;&gt; /etc/mdadm.conf
# mdadm --detail --scan --verbose &gt;&gt; /etc/mdadm.conf  
# cat /etc/mdadm.conf
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Save-RAID-Configurations.png" alt="Save RAID Configurations"></p><p><em>保存 RAID 配置</em></p><p>就這樣，我們在這裏看到，如何通過使用兩個硬盤配置具有條帶化的 RAID 0 。在接下來的文章中，我們將看到如何設置 RAID 1。</p><hr>`,78)),n("p",null,[e[2]||(e[2]=t("via: ",-1)),i(d,{href:"http://www.tecmint.com/create-raid0-in-linux/"},{default:a(()=>[...e[1]||(e[1]=[t("http://www.tecmint.com/create-raid0-in-linux/",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=t("作者：",-1)),i(d,{href:"http://www.tecmint.com/author/babinlonston/"},{default:a(()=>[...e[3]||(e[3]=[t("Babin Lonston",-1)])]),_:1}),e[7]||(e[7]=t(" 譯者：",-1)),i(d,{href:"https://github.com/strugglingyouth"},{default:a(()=>[...e[4]||(e[4]=[t("strugglingyouth",-1)])]),_:1}),e[8]||(e[8]=t(" 校對：",-1)),i(d,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[11]||(e[11]=t("本文由 ",-1)),i(d,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[9]||(e[9]=[t("LCTT",-1)])]),_:1}),e[12]||(e[12]=t(" 原創翻譯，",-1)),i(d,{href:"https://linux.cn/"},{default:a(()=>[...e[10]||(e[10]=[t("Linux中國",-1)])]),_:1}),e[13]||(e[13]=t(" 榮譽推出",-1))])])}const x=r(c,[["render",s]]);export{h as __pageData,x as default};
